use std::{
    env, fs, io,
    net::{SocketAddr, TcpStream, ToSocketAddrs},
    path::Path,
    process::{Command, Output},
    time::Duration,
};

use anyhow::{Context, Result, anyhow, bail};
use url::Url;

use crate::project::Project;

const DEFAULT_AMQP_URL: &str = "amqp://toolbox:toolbox-local-only@127.0.0.1:5672/%2f";
const COMPOSE_RELATIVE: &str = ".toolbox/rabbitmq/compose.yaml";
const CHECK_MANIFEST_RELATIVE: &str = ".toolbox/rabbitmq/check/Cargo.toml";
const CHECK_SOURCE_RELATIVE: &str = ".toolbox/rabbitmq/check/src/main.rs";
const GENERATED_HEADER: &str =
    "# Generated by devtoolbox. Re-run with --force to replace local edits.\n";

struct GeneratedFile {
    relative: &'static str,
    content: String,
}

pub fn installed(project: &Project) -> bool {
    project.root().join(COMPOSE_RELATIVE).is_file()
}

pub fn add(project: &Project, dry_run: bool, force: bool) -> Result<()> {
    let generated = generated_files();
    let env_path = project.root().join(".env.example");
    let gitignore_path = project.root().join(".gitignore");
    let env_content = merge_env(&read_optional(&env_path)?)?;
    let gitignore_content = merge_gitignore(&read_optional(&gitignore_path)?)?;

    let mut plan = Vec::new();
    for file in &generated {
        let path = project.root().join(file.relative);
        plan.push((path.clone(), change_kind(&path, &file.content)?));
    }
    plan.push((env_path.clone(), change_kind(&env_path, &env_content)?));
    plan.push((
        gitignore_path.clone(),
        change_kind(&gitignore_path, &gitignore_content)?,
    ));

    println!("Projet Rust détecté : {}", project.root().display());
    for (path, kind) in &plan {
        println!("  {kind:>9}  {}", relative_display(project.root(), path));
    }

    if dry_run {
        println!("Dry-run : aucun fichier modifié.");
        return Ok(());
    }

    for file in &generated {
        let path = project.root().join(file.relative);
        if path.is_file() {
            let existing = fs::read_to_string(&path)
                .with_context(|| format!("lecture de {}", path.display()))?;
            if existing != file.content && !force {
                bail!(
                    "{} existe et diffère du contenu généré ; utilisez --force après revue",
                    relative_display(project.root(), &path)
                );
            }
        }
    }

    for file in generated {
        write_if_changed(&project.root().join(file.relative), &file.content)?;
    }
    write_if_changed(&env_path, &env_content)?;
    write_if_changed(&gitignore_path, &gitignore_content)?;

    println!("RabbitMQ ajouté. Étape suivante : toolbox up");
    Ok(())
}

pub fn up(project: &Project) -> Result<()> {
    ensure_generated(project)?;
    let amqp_url = env::var("RABBITMQ_URL").unwrap_or_else(|_| DEFAULT_AMQP_URL.to_owned());
    let parsed = Url::parse(&amqp_url).context("RABBITMQ_URL n'est pas une URL valide")?;
    validate_scheme(&parsed)?;
    if !is_local(&parsed) {
        bail!(
            "toolbox up démarre uniquement le provider local ; utilisez toolbox doctor pour tester un RABBITMQ_URL distant"
        );
    }

    let compose = project.root().join(COMPOSE_RELATIVE);
    let mut command = Command::new("docker");
    command
        .arg("compose")
        .arg("-p")
        .arg(project.compose_project_name())
        .arg("-f")
        .arg(&compose)
        .args(["up", "-d", "--wait", "--wait-timeout", "90", "rabbitmq"]);

    println!("Démarrage de RabbitMQ…");
    let output = run_output(&mut command, "docker compose up")?;
    ensure_success(&output, "le démarrage de RabbitMQ")?;

    println!("RabbitMQ est healthy. Vérification AMQP depuis le projet Rust…");
    let roundtrip = run_roundtrip(project, &amqp_url)?;
    println!("{}", roundtrip.trim());
    println!("Prêt : exportez RABBITMQ_URL pour cibler un broker distant sans changer le code.");
    Ok(())
}

pub fn down(project: &Project) -> Result<()> {
    ensure_generated(project)?;
    let mut command = Command::new("docker");
    command
        .arg("compose")
        .arg("-p")
        .arg(project.compose_project_name())
        .arg("-f")
        .arg(project.root().join(COMPOSE_RELATIVE))
        .arg("down");
    let output = run_output(&mut command, "docker compose down")?;
    ensure_success(&output, "l'arrêt de RabbitMQ")?;
    println!("RabbitMQ arrêté ; le volume de données est conservé.");
    Ok(())
}

pub fn doctor(project: &Project) -> Result<()> {
    let amqp_url = env::var("RABBITMQ_URL").unwrap_or_else(|_| DEFAULT_AMQP_URL.to_owned());
    let parsed = Url::parse(&amqp_url).context("RABBITMQ_URL n'est pas une URL valide")?;
    validate_scheme(&parsed)?;
    let endpoint = endpoint(&parsed)?;
    let local = is_local(&parsed);
    let mut failed = false;

    println!("Diagnostic RabbitMQ");
    report(
        project.root().join(COMPOSE_RELATIVE).is_file(),
        "câblage toolbox présent",
        &mut failed,
    );
    println!("  [info] endpoint {}", safe_endpoint(&parsed));
    println!(
        "  [info] provider {}",
        if local { "local" } else { "distant" }
    );

    if local {
        let docker_ok = check_command(&mut docker_version_command());
        report(docker_ok, "CLI et daemon Docker accessibles", &mut failed);

        if docker_ok && project.root().join(COMPOSE_RELATIVE).is_file() {
            let compose_ok = check_command(&mut compose_config_command(project));
            report(compose_ok, "configuration Compose valide", &mut failed);

            let broker_ok = check_command(&mut rabbitmq_ping_command(project));
            report(
                broker_ok,
                "conteneur RabbitMQ actif et répondant",
                &mut failed,
            );
        }
    } else {
        println!("  [skip] Docker ignoré pour un provider distant");
    }

    let tcp_ok = connect_tcp(&endpoint).is_ok();
    report(
        tcp_ok,
        &format!("connexion TCP vers {endpoint}"),
        &mut failed,
    );

    if tcp_ok && project.root().join(CHECK_MANIFEST_RELATIVE).is_file() {
        match run_roundtrip(project, &amqp_url) {
            Ok(output) => {
                report(true, output.trim(), &mut failed);
            }
            Err(error) => {
                report(
                    false,
                    &format!("aller-retour AMQP : {error:#}"),
                    &mut failed,
                );
            }
        }
    }

    if failed {
        bail!("diagnostic en échec ; corrigez les lignes [fail] ci-dessus")
    }

    println!("Diagnostic terminé sans erreur.");
    Ok(())
}

fn generated_files() -> Vec<GeneratedFile> {
    vec![
        GeneratedFile {
            relative: COMPOSE_RELATIVE,
            content: format!("{GENERATED_HEADER}{COMPOSE}"),
        },
        GeneratedFile {
            relative: CHECK_MANIFEST_RELATIVE,
            content: format!("{GENERATED_HEADER}{CHECK_MANIFEST}"),
        },
        GeneratedFile {
            relative: CHECK_SOURCE_RELATIVE,
            content: format!(
                "// Generated by devtoolbox. This binary verifies the project-to-broker path.\n{CHECK_SOURCE}"
            ),
        },
    ]
}

fn ensure_generated(project: &Project) -> Result<()> {
    for relative in [
        COMPOSE_RELATIVE,
        CHECK_MANIFEST_RELATIVE,
        CHECK_SOURCE_RELATIVE,
    ] {
        let path = project.root().join(relative);
        if !path.is_file() {
            bail!("{} manque ; exécutez toolbox add rabbitmq", path.display());
        }
    }
    Ok(())
}

fn run_roundtrip(project: &Project, amqp_url: &str) -> Result<String> {
    let manifest = project.root().join(CHECK_MANIFEST_RELATIVE);
    let target = project.root().join(".toolbox/cache/target");
    let mut command = Command::new("cargo");
    command
        .args(["run", "--quiet", "--manifest-path"])
        .arg(manifest)
        .env("CARGO_TARGET_DIR", target)
        .env("RABBITMQ_URL", amqp_url);
    let output = run_output(&mut command, "le client de vérification Rust")?;
    ensure_success(&output, "l'aller-retour AMQP")?;
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

fn docker_version_command() -> Command {
    let mut command = Command::new("docker");
    command.args(["info", "--format", "{{.ServerVersion}}"]);
    command
}

fn compose_config_command(project: &Project) -> Command {
    let mut command = Command::new("docker");
    command
        .arg("compose")
        .arg("-p")
        .arg(project.compose_project_name())
        .arg("-f")
        .arg(project.root().join(COMPOSE_RELATIVE))
        .args(["config", "--quiet"]);
    command
}

fn rabbitmq_ping_command(project: &Project) -> Command {
    let mut command = Command::new("docker");
    command
        .arg("compose")
        .arg("-p")
        .arg(project.compose_project_name())
        .arg("-f")
        .arg(project.root().join(COMPOSE_RELATIVE))
        .args([
            "exec",
            "-T",
            "rabbitmq",
            "rabbitmq-diagnostics",
            "-q",
            "ping",
        ]);
    command
}

fn check_command(command: &mut Command) -> bool {
    command
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

fn run_output(command: &mut Command, label: &str) -> Result<Output> {
    command
        .output()
        .with_context(|| format!("impossible d'exécuter {label}"))
}

fn ensure_success(output: &Output, label: &str) -> Result<()> {
    if output.status.success() {
        return Ok(());
    }

    let stderr = String::from_utf8_lossy(&output.stderr);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let details = if stderr.trim().is_empty() {
        stdout.trim()
    } else {
        stderr.trim()
    };
    bail!("{label} a échoué : {details}")
}

fn connect_tcp(endpoint: &SocketAddr) -> io::Result<TcpStream> {
    TcpStream::connect_timeout(endpoint, Duration::from_secs(3))
}

fn endpoint(url: &Url) -> Result<SocketAddr> {
    let host = url
        .host_str()
        .context("RABBITMQ_URL ne contient pas d'hôte")?;
    let port = url
        .port_or_known_default()
        .ok_or_else(|| anyhow!("RABBITMQ_URL ne contient pas de port"))?;
    (host, port)
        .to_socket_addrs()
        .with_context(|| format!("résolution DNS de {host}"))?
        .next()
        .ok_or_else(|| anyhow!("aucune adresse trouvée pour {host}:{port}"))
}

fn validate_scheme(url: &Url) -> Result<()> {
    if matches!(url.scheme(), "amqp" | "amqps") {
        Ok(())
    } else {
        bail!("RABBITMQ_URL doit utiliser amqp:// ou amqps://")
    }
}

fn is_local(url: &Url) -> bool {
    matches!(url.host_str(), Some("127.0.0.1" | "localhost" | "::1"))
}

fn safe_endpoint(url: &Url) -> String {
    let host = url.host_str().unwrap_or("<hôte manquant>");
    let port = url.port_or_known_default().unwrap_or(5672);
    format!("{}://{host}:{port}{}", url.scheme(), url.path())
}

fn report(ok: bool, message: &str, failed: &mut bool) {
    if ok {
        println!("  [ok]   {message}");
    } else {
        println!("  [fail] {message}");
        *failed = true;
    }
}

fn change_kind(path: &Path, desired: &str) -> Result<&'static str> {
    if !path.exists() {
        return Ok("create");
    }
    let current =
        fs::read_to_string(path).with_context(|| format!("lecture de {}", path.display()))?;
    if current == desired {
        Ok("unchanged")
    } else {
        Ok("update")
    }
}

fn write_if_changed(path: &Path, content: &str) -> Result<()> {
    if path.is_file() && fs::read_to_string(path)? == content {
        return Ok(());
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("création de {}", parent.display()))?;
    }
    fs::write(path, content).with_context(|| format!("écriture de {}", path.display()))
}

fn read_optional(path: &Path) -> Result<String> {
    match fs::read_to_string(path) {
        Ok(content) => Ok(content),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(String::new()),
        Err(error) => Err(error).with_context(|| format!("lecture de {}", path.display())),
    }
}

fn merge_env(existing: &str) -> Result<String> {
    let base = strip_managed_block(existing, "rabbitmq")?;
    let defaults = [
        ("RABBITMQ_URL", DEFAULT_AMQP_URL),
        ("TOOLBOX_RABBITMQ_MANAGEMENT_URL", "http://127.0.0.1:15672"),
    ];
    if defaults
        .iter()
        .all(|(key, _)| contains_assignment(existing, key))
    {
        return Ok(existing.to_owned());
    }
    let mut body = Vec::new();
    for (key, value) in defaults {
        if !contains_assignment(&base, key) {
            body.push(format!("{key}={value}"));
        }
    }
    append_managed_block(&base, "rabbitmq", &body.join("\n"))
}

fn merge_gitignore(existing: &str) -> Result<String> {
    let base = strip_managed_block(existing, "cache")?;
    append_managed_block(&base, "cache", ".toolbox/cache/")
}

fn strip_managed_block(existing: &str, label: &str) -> Result<String> {
    let start_marker = format!("# >>> devtoolbox:{label}");
    let end_marker = format!("# <<< devtoolbox:{label}");
    let Some(start) = existing.find(&start_marker) else {
        return Ok(existing.to_owned());
    };
    let relative_end = existing[start..]
        .find(&end_marker)
        .ok_or_else(|| anyhow!("bloc {label} incomplet : marqueur de fin absent"))?;
    let end = start + relative_end + end_marker.len();
    let mut base = String::new();
    base.push_str(existing[..start].trim_end_matches('\n'));
    if !base.is_empty() && !existing[end..].trim().is_empty() {
        base.push('\n');
    }
    base.push_str(existing[end..].trim_start_matches('\n'));
    Ok(base)
}

fn append_managed_block(base: &str, label: &str, body: &str) -> Result<String> {
    if body.is_empty() {
        let mut output = base.trim_end_matches('\n').to_owned();
        if !output.is_empty() {
            output.push('\n');
        }
        return Ok(output);
    }

    let mut output = base.trim_end_matches('\n').to_owned();
    if !output.is_empty() {
        output.push_str("\n\n");
    }
    output.push_str(&format!(
        "# >>> devtoolbox:{label}\n{body}\n# <<< devtoolbox:{label}\n"
    ));
    Ok(output)
}

fn contains_assignment(content: &str, key: &str) -> bool {
    content.lines().any(|line| {
        line.trim_start()
            .strip_prefix(key)
            .is_some_and(|suffix| suffix.trim_start().starts_with('='))
    })
}

fn relative_display(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .display()
        .to_string()
}

const COMPOSE: &str = r#"services:
  rabbitmq:
    image: rabbitmq:4.3.3-management@sha256:d8b3d416236ae5ba3f6a9f4e4651fdacda01780181a7d83a71b640248d8f0a69
    environment:
      RABBITMQ_DEFAULT_USER: toolbox
      RABBITMQ_DEFAULT_PASS: toolbox-local-only
    ports:
      - "127.0.0.1:${TOOLBOX_RABBITMQ_PORT:-5672}:5672"
      - "127.0.0.1:${TOOLBOX_RABBITMQ_MANAGEMENT_PORT:-15672}:15672"
    volumes:
      - rabbitmq-data:/var/lib/rabbitmq
    healthcheck:
      test: ["CMD", "rabbitmq-diagnostics", "-q", "ping"]
      interval: 3s
      timeout: 5s
      retries: 30
      start_period: 10s

volumes:
  rabbitmq-data:
"#;

const CHECK_MANIFEST: &str = r#"[workspace]

[package]
name = "toolbox-rabbitmq-check"
version = "0.1.0"
edition = "2024"
publish = false

[dependencies]
futures-lite = "2"
lapin = "=4.10.0"
tokio = { version = "1", features = ["macros", "rt-multi-thread", "time"] }
"#;

const CHECK_SOURCE: &str = r#"
use std::{env, io, process, time::Duration};

use futures_lite::stream::StreamExt;
use lapin::{
    BasicProperties, Connection, ConnectionProperties,
    options::{BasicAckOptions, BasicConsumeOptions, BasicPublishOptions, QueueDeclareOptions},
    types::FieldTable,
};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let url = env::var("RABBITMQ_URL").map_err(|_| {
        io::Error::new(io::ErrorKind::NotFound, "RABBITMQ_URL est absente")
    })?;
    let connection = Connection::connect(
        &url,
        ConnectionProperties::default().with_connection_name("devtoolbox-check".into()),
    )
    .await?;
    let channel = connection.create_channel().await?;
    let queue_name = format!("devtoolbox.check.{}", process::id());
    channel
        .queue_declare(
            queue_name.clone().into(),
            QueueDeclareOptions {
                exclusive: true,
                auto_delete: true,
                ..QueueDeclareOptions::default()
            },
            FieldTable::default(),
        )
        .await?;
    let mut consumer = channel
        .basic_consume(
            queue_name.clone().into(),
            "devtoolbox-check".into(),
            BasicConsumeOptions::default(),
            FieldTable::default(),
        )
        .await?;
    let payload = b"devtoolbox-rabbitmq-roundtrip";
    channel
        .basic_publish(
            "".into(),
            queue_name.into(),
            BasicPublishOptions::default(),
            payload,
            BasicProperties::default(),
        )
        .await?
        .await?;

    let delivery = tokio::time::timeout(Duration::from_secs(10), consumer.next())
        .await?
        .ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "consumer interrompu"))??;
    if delivery.data != payload {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "payload AMQP altéré").into());
    }
    delivery.ack(BasicAckOptions::default()).await?;
    connection.close(200, "check complete".into()).await?;
    println!("aller-retour AMQP réussi (publication + consommation)");
    Ok(())
}
"#;

#[cfg(test)]
mod tests {
    use super::{contains_assignment, is_local, merge_env, strip_managed_block};
    use url::Url;

    #[test]
    fn merge_env_is_idempotent() {
        let once = merge_env("APP_ENV=dev\n").expect("first merge");
        let twice = merge_env(&once).expect("second merge");
        assert_eq!(once, twice);
        assert_eq!(once.matches("RABBITMQ_URL=").count(), 1);
    }

    #[test]
    fn merge_env_preserves_existing_connection_url() {
        let merged = merge_env("RABBITMQ_URL=amqps://example.invalid/%2f\n").expect("merge");
        assert!(merged.contains("RABBITMQ_URL=amqps://example.invalid/%2f"));
        assert_eq!(merged.matches("RABBITMQ_URL=").count(), 1);
    }

    #[test]
    fn detects_assignments_without_matching_similar_names() {
        assert!(contains_assignment(" RABBITMQ_URL = value", "RABBITMQ_URL"));
        assert!(!contains_assignment(
            "OTHER_RABBITMQ_URL=value",
            "RABBITMQ_URL"
        ));
    }

    #[test]
    fn malformed_managed_block_is_rejected() {
        assert!(strip_managed_block("# >>> devtoolbox:rabbitmq\nvalue", "rabbitmq").is_err());
    }

    #[test]
    fn classifies_only_loopback_hosts_as_local() {
        assert!(is_local(&Url::parse("amqp://localhost:5672").unwrap()));
        assert!(is_local(&Url::parse("amqp://127.0.0.1:5672").unwrap()));
        assert!(!is_local(
            &Url::parse("amqps://rabbitmq.example:5671").unwrap()
        ));
    }
}
